package com.metaplatform.agent.runs;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest; import org.springframework.test.context.TestPropertySource; import java.time.Instant; import static org.assertj.core.api.Assertions.assertThat;
@DataJpaTest @TestPropertySource(properties={"spring.flyway.enabled=false","spring.jpa.hibernate.ddl-auto=create-drop"}) class TaskRepositoryTest { @Autowired TaskRepository repository; @Test void crudAndCustomQuery(){ Instant now=Instant.parse("2026-07-01T00:00:00Z"); repository.save(TaskEntity.builder().taskId("task-1").runId("run-1").assigneeAgent("a").objective("o").input("{}").permissionsRef("p").budget("{}").status("PENDING").createdAt(now).updatedAt(now).build()); assertThat(repository.findById("task-1")).isPresent(); assertThat(repository.findByRunIdOrderByCreatedAtAsc("run-1")).extracting(TaskEntity::getTaskId).containsExactly("task-1"); } }
